	'tt1_t' => '08:30',
	'tt1_w' => 'Arrivée et marche de l’étage : lumière, bruit, circulations et usage de la pièce (jusqu’à 10:00).',
	'tt2_t' => '10:00',
	'tt2_w' => 'Début des séances aux postes : 20 minutes par personne à son propre bureau, jusqu’à 15 postes par consultant.',
